FILE: app/src/orbit-camera.ts
```ts
import {
  attachControl,
  createArcRotateCamera,
  enableArcRotateKeyboardControls,
} from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function createOrbitCamera(
  canvas: HTMLCanvasElement,
  scene: SceneContext
): ArcRotateCamera {
  const camera = createArcRotateCamera(0, Math.PI / 2, 10, {
    x: 0,
    y: 0,
    z: 0,
  });

  enableArcRotateKeyboardControls();
  attachControl(camera, canvas, scene, { keyboard: true });

  return camera;
}
```

I added `src/orbit-camera.ts` so it creates an `ArcRotateCamera` 10 units from the origin, attaches the library’s pointer controls to the canvas, and enables the library’s arrow-key controls. I wasn’t sure whether these symbols are re-exported from the `@babylonjs/lite` root or only from subpaths, so I used the root import name you specified.
